const item = $input.item.json;
const raw = item.stdout || '';
const lines = raw.split('\n');
const exitLineIndex = lines.findIndex((l) => l.startsWith('DC005_EXIT_CODE='));
const exitCode = exitLineIndex >= 0 ? parseInt(lines[exitLineIndex].split('=')[1], 10) : null;
const stdoutText = (exitLineIndex >= 0 ? lines.slice(0, exitLineIndex) : lines).join('\n');
const idMatch = stdoutText.match(/ingested_content_id:\s+(ic_[A-Za-z0-9]+)/);
const success = exitCode === 0 && idMatch !== null;
return {
  json: {
    routeKey: success ? 'continue' : 'technical_failure',
    stage: 'I030 Content Ingestion',
    ingestedContentId: idMatch ? idMatch[1] : null,
    exitCode,
    safeErrorSummary: success ? null : `I030 Content Ingestion failed (exit ${exitCode}).`,
    stdoutExcerpt: stdoutText.slice(0, 2000),
    stderrExcerpt: (item.stderr || '').slice(0, 1000),
  },
};

const item = $input.item.json;
const raw = item.stdout || '';
const lines = raw.split('\n');
const exitLineIndex = lines.findIndex((l) => l.startsWith('DC005_EXIT_CODE='));
const exitCode = exitLineIndex >= 0 ? parseInt(lines[exitLineIndex].split('=')[1], 10) : null;
const stdoutText = (exitLineIndex >= 0 ? lines.slice(0, exitLineIndex) : lines).join('\n');
const jsonStart = stdoutText.indexOf('{');
let record = null;
if (jsonStart >= 0) {
  try { record = JSON.parse(stdoutText.slice(jsonStart)); } catch (e) { record = null; }
}
const success = exitCode === 0 && record !== null;
return {
  json: {
    routeKey: success ? 'continue' : 'technical_failure',
    stage: 'I031 Editorial Package',
    editorialPackageId: record ? record.editorial_package_id : null,
    primaryHeadline: record ? record.primary_headline : null,
    executiveSummary: record ? record.executive_summary : null,
    coreMessage: record ? record.core_message : null,
    callToAction: record ? record.call_to_action : null,
    keyInsights: record ? record.key_insights : [],
    pullQuotes: record ? record.pull_quotes : [],
    exitCode,
    safeErrorSummary: success ? null : `I031 Editorial Package failed (exit ${exitCode}).`,
    stdoutExcerpt: stdoutText.slice(0, 2000),
    stderrExcerpt: (item.stderr || '').slice(0, 1000),
  },
};

