const item = $input.item.json;
const raw = item.stdout || '';
const lines = raw.split('\n');
const exitLineIndex = lines.findIndex((l) => l.startsWith('DC005_EXIT_CODE='));
const exitCode = exitLineIndex >= 0 ? parseInt(lines[exitLineIndex].split('=')[1], 10) : null;
const stdoutText = (exitLineIndex >= 0 ? lines.slice(0, exitLineIndex) : lines).join('\n');
const idMatch = stdoutText.match(/carousel_id:\s+(car_[A-Za-z0-9]+)/);
const statusMatch = stdoutText.match(/overall_status:\s+(\w+)/);
const slideRegex = /\[slide (\d+)\] (\S+) . (\S+) . (\S+)/g;
const slides = [];
let m;
while ((m = slideRegex.exec(stdoutText)) !== null) {
  slides.push({ slideNumber: parseInt(m[1], 10), slideType: m[2], status: m[3], imageUrl: m[4] });
}
const overallStatus = statusMatch ? statusMatch[1] : null;
const success = exitCode === 0 && idMatch !== null && overallStatus === 'completed';
return {
  json: {
    routeKey: success ? 'continue' : 'technical_failure',
    stage: 'I034 Live Carousel Rendering',
    carouselId: idMatch ? idMatch[1] : null,
    overallStatus,
    slides,
    exitCode,
    safeErrorSummary: success ? null : `I034 Live Carousel Rendering did not complete successfully (exit ${exitCode}, overall_status=${overallStatus}).`,
    stdoutExcerpt: stdoutText.slice(0, 3000),
    stderrExcerpt: (item.stderr || '').slice(0, 1000),
  },
};

